/* @lc app=leetcode id=3584 lang=kotlin */ class Solution { fun maximumProduct(nums: IntArray, m: Int): Long = nums.runningFold(Int.MAX_VALUE) { a, b -> minOf(a, b) }.drop(1).let { pmn -> nums.runningFold(Int.MIN_VALUE) { a, b -> maxOf(a, b) }.drop(1).let { pmx -> (m - 1 until nums.size).maxOf { j -> maxOf(nums[j].toLong() * pmn[j - m + 1], nums[j].toLong() * pmx[j - m + 1]) } } } }